before_source:
ALLOWED_NEXT = {
    "DRAFT": {"PUBLISHED"},
    "DRAFT_REVIEW": {"APPROVED"},
    "PUBLISHED": {"ARCHIVED"},
    "ARCHIVED": set(),
}


def can_publish(current, target):
    """判断当前状态能否流转到目标状态。"""
    for state, targets in ALLOWED_NEXT.items():
        if current.startswith(state):
            return target in targets
    return False

verification_tests:
from target import can_publish


def test_draft_review_uses_its_own_white_list():
    assert can_publish("DRAFT_REVIEW", "APPROVED") is True


def test_draft_can_be_published():
    assert can_publish("DRAFT", "PUBLISHED") is True


def test_unknown_state_cannot_transition():
    assert can_publish("REMOVED", "PUBLISHED") is False
